corrected_code:
use Illuminate\Support\Facades\Broadcast;
use App\Models\User;
use App\Models\Document;

// routes/channels.php
Broadcast::channel('document.{docUuid}', function (User $user, string $docUuid) {
    $document = Document::where('uuid', $docUuid)->first();
    if (!$document || !$user->can('view', $document)) {
        return false;
    }

    return ['id' => $user->id, 'name' => $user->name];
});
